    public void audit(@Val Person person, ServerHttpConnection connection, Audit audit) {
        audit.record(Audit.line("PERSON_ADDED", person.sheetId(), Audit.user(connection), "name=" + person.name(),
                "grade=" + person.grade()));
    }
